// Orbit Gallery · snapcn — https://snapcn.dev/docs/scenes/orbit-gallery
// snapcn UI Core · snapcn — https://snapcn.dev/docs/components

import {
  type ComponentProps,
  createContext,
  forwardRef,
  type ReactNode,
  useContext,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Img,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  Sequence,
  type SequenceControls,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[snap-cn-ui] parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[snap-cn-ui] parseColor could not parse "${s}"; using black.`,
      );
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[snap-cn-ui] mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[snap-cn-ui] mixOklch could not parse "${trimmed}"; using black.`,
      );
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface SnapCnTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `SnapCnUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `SnapCnUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: SnapCnTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: SnapCnTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface SnapCnThemeContextValue {
  theme?: Partial<SnapCnTheme>;
  mode?: "light" | "dark";
}

const SnapCnThemeContext = createContext<SnapCnThemeContextValue>({});

function useSnapCnTheme(
  override?: Partial<SnapCnTheme>,
  modeOverride?: "light" | "dark",
): SnapCnTheme {
  const ctx = useContext(SnapCnThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

const TWO_PI = Math.PI * 2;
/** Lookup resolution for the arc-length reparameterization table. */
const ARC_SAMPLES = 1024;

export interface OrbitGalleryProps {
  title?: string;
  subtitle?: string;
  /** Pill CTA under the subtitle. Empty string hides it. */
  buttonLabel?: string;
  /**
   * Card artwork URLs, cycled along the spiral stream. A URL that fails to load
   * falls back to a gradient tile rather than breaking playback. Pass `[]` to
   * render self-contained editorial gradient tiles (no network).
   */
  images?: string[];
  /** How many times the Archimedean spiral winds from the edge to the center. */
  turns?: number;
  /** Arc spacing between cards along the stream (smaller = denser). */
  spacing?: number;
  /** Radius scale — larger pushes the outer coils off-frame, same coil gaps. */
  spread?: number;
  /** How much cards shrink toward the center (0 = uniform). */
  sizeAttenuation?: number;
  /** Card long-edge in px at the outer radius, on the reference 600px canvas. */
  imageSize?: number;
  /** Card width / height (portrait < 1). */
  cardAspect?: number;
  /** Percent of the path over which a card fades in at the outer end. */
  fadeIn?: number;
  /** Percent of the path over which a card fades out at the center end. */
  fadeOut?: number;
  /** Corner rounding, matching the reference's 0–20 scale (0 = sharp). */
  cornerRadius?: number;
  /** Seconds for the stream to flow one full turnover into the center. */
  orbitSeconds?: number;
  /** Overrides the design system's `background`. */
  background?: string;
  /** Overrides the design system's `foreground`. */
  textColor?: string;
  /** Design-system token overrides. */
  theme?: Partial<SnapCnTheme>;
  /** Defaults to `"dark"` — the orbit is a cinematic stage, lit for dark. */
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
  /** Tiny captions pinned to the bottom edge. Empty strings hide them. */
  footerLeft?: string;
  footerCenter?: string;
  footerRight?: string;
  speed?: number;
  className?: string;
}

const SAMPLE_IMAGES = Array.from(
  { length: 16 },
  (_, i) => `https://picsum.photos/seed/snap-orbit-${i + 1}/440/560`,
);

/** Editorial two-stop gradients used for tiles without a (working) photo. */
const PLACEHOLDER_FILLS = [
  "linear-gradient(135deg, #2b5fd9, #14306e)",
  "linear-gradient(135deg, #c96f2f, #7a3c12)",
  "linear-gradient(135deg, #e8e4da, #b6ad99)",
  "linear-gradient(135deg, #c8332b, #6e1511)",
  "linear-gradient(135deg, #b9a0d0, #6f5590)",
  "linear-gradient(135deg, #4c6b3c, #24361a)",
  "linear-gradient(135deg, #1f4dd8, #0d2262)",
  "linear-gradient(135deg, #d9d2c5, #a09684)",
];

const FONT_STACK = "Inter, -apple-system, BlinkMacSystemFont, sans-serif";

/**
 * Archimedean spiral point at parameter `n` in [0, 1]: n=0 is the outer edge
 * (radius R), n=1 is the center (radius 0). Because the radius falls off
 * LINEARLY, every coil is separated by the same radial gap (R / turns) — the
 * even "circle to circle" spacing. `y` is flipped so the spiral reads clockwise
 * from the top like the reference.
 */
function archimedeanPoint(
  n: number,
  R: number,
  turns: number,
): { x: number; y: number } {
  const ang = n * turns * TWO_PI;
  const rad = R * (1 - n);
  return { x: rad * Math.cos(ang), y: -rad * Math.sin(ang) };
}

/**
 * Build the arc-length reparameterization table for a spiral of `turns` turns.
 * Sampling the path by even parameter would bunch cards near the center (where
 * the coils are short); sampling by even ARC length spaces them evenly. The
 * spiral's shape is radius-independent, so the table is built once at R=1 and
 * returns, for each even arc fraction, the spiral parameter `n` that lands
 * there.
 */
function buildArcTable(turns: number, samples = 2000): Float64Array {
  const cum = new Float64Array(samples + 1);
  let prev = archimedeanPoint(0, 1, turns);
  for (let k = 1; k <= samples; k++) {
    const pt = archimedeanPoint(k / samples, 1, turns);
    cum[k] = cum[k - 1] + Math.hypot(pt.x - prev.x, pt.y - prev.y);
    prev = pt;
  }
  const total = cum[samples] || 1;

  const nForArc = new Float64Array(ARC_SAMPLES + 1);
  let j = 0;
  for (let a = 0; a <= ARC_SAMPLES; a++) {
    const target = (a / ARC_SAMPLES) * total;
    while (j < samples && cum[j + 1] < target) j++;
    const seg = cum[j + 1] - cum[j];
    const f2 = seg > 0 ? (target - cum[j]) / seg : 0;
    nForArc[a] = (j + f2) / samples;
  }
  return nForArc;
}

/** Map an arc fraction `s` in [0, 1) to the spiral parameter `n` (interpolated
 * so motion stays smooth, never quantized into visible steps). */
function arcToN(s: number, nForArc: Float64Array): number {
  const x = Math.max(0, Math.min(ARC_SAMPLES, s * ARC_SAMPLES));
  const i = Math.floor(x);
  const a = nForArc[i];
  const b = nForArc[Math.min(i + 1, ARC_SAMPLES)];
  return a + (b - a) * (x - i);
}

/** Radius scale for the spiral: R = 0.48·min · (1 + (spread − 1)·0.18). */
function ringRadius(minDim: number, spread: number): number {
  return 0.48 * minDim * (1 + (spread - 1) * 0.18);
}

/** Card size multiplier from its distance to the center — smaller toward the
 * middle. `dist/R` clamped to 1, raised to `sizeAttenuation/2`. */
function sizeScale(dist: number, R: number, sizeAttenuation: number): number {
  return sizeAttenuation > 0
    ? Math.min(dist / R, 1) ** (sizeAttenuation * 0.5)
    : 1;
}

/**
 * A root-relative asset is a `public/` file. Only the site's own Player serves
 * it at that path; Remotion Studio and a render know its URL through
 * `staticFile()` alone — so every environment but the Player rewrites it.
 */
function resolveSrc(src: string): string {
  const isLocal = src.startsWith("/") && !src.startsWith("//");
  if (!isLocal || getRemotionEnvironment().isPlayer) return src;
  // A value that already came out of staticFile() carries the static base
  // (`/static-<hash>/…`); running it through again would prefix it twice.
  const base = staticFile("_").slice(0, -2);
  if (base && src.startsWith(`${base}/`)) return src;
  try {
    return staticFile(src.replace(/^\/+/, ""));
  } catch {
    return src;
  }
}

/**
 * One card face: the editorial gradient is always painted as the base layer,
 * and a photo (when provided) overlays it. A failed load flips to `errored` so
 * the gradient shows through — crucially, the `onError` handler also stops
 * Remotion's <Img> from calling cancelRender(), which would otherwise halt the
 * whole player when an external image is blocked or slow to fail. */
function OrbitTile({ src, fill }: { src: string | undefined; fill: string }) {
  const [errored, setErrored] = useState(false);
  return (
    <>
      <div style={{ position: "absolute", inset: 0, backgroundImage: fill }} />
      {src && !errored ? (
        <Img
          showInTimeline={false}
          src={resolveSrc(src)}
          crossOrigin="anonymous"
          onError={() => setErrored(true)}
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
      ) : null}
    </>
  );
}

function OrbitGalleryScene({
  title = "A whole new universe",
  subtitle = "Article — The Design Process",
  buttonLabel = "Explore",
  images,
  turns = 3,
  spacing = 5,
  spread = 7,
  sizeAttenuation = 2,
  imageSize = 172,
  cardAspect = 0.78,
  fadeIn = 20,
  fadeOut = 0,
  cornerRadius = 5,
  orbitSeconds = 40,
  background,
  textColor,
  theme,
  mode,
  fontFamily,
  footerLeft = "",
  footerCenter = "",
  footerRight = "",
  speed = 1,
  className,
}: OrbitGalleryProps) {
  const frame = useCurrentFrame();
  const { width, height, fps, durationInFrames } = useVideoConfig();
  const tokens = useSnapCnTheme(theme, mode ?? "dark");
  const face = resolveFont(fontFamily ?? tokens.fontFamily) ?? FONT_STACK;
  const stage = background ?? tokens.background;
  const ink = textColor ?? tokens.foreground;
  const t = frame * speed;

  const minDim = Math.min(width, height);
  const R = ringRadius(minDim, spread);
  const baseSize = imageSize * (minDim / 600);
  const artwork = images ?? SAMPLE_IMAGES;
  const nImgs = artwork.length || 1;

  // Arc-length table (shape-only, so it depends on `turns` alone).
  const nForArc = useMemo(() => buildArcTable(turns), [turns]);

  const stepFrac = Math.max(0.005, (spacing * 0.5) / 100);
  const slots = Math.min(400, Math.ceil(1 / stepFrac) + 2);

  // Seamless inward flow: advance the stream by a whole number of card-steps
  // over the composition so the loop has no visible jump.
  const stepsPerLoop = Math.max(
    1,
    Math.round(durationInFrames / fps / orbitSeconds / stepFrac),
  );
  const base =
    ((((t / durationInFrames) * stepsPerLoop * stepFrac) % 1) + 1) % 1;

  const cards = [];
  for (let i = 0; i < slots; i++) {
    const s = (((base + i * stepFrac) % 1) + 1) % 1;
    const n = arcToN(s, nForArc);
    cards.push({ key: i, tt: s * 100, n, imgIdx: i % nImgs });
  }
  // Draw outer coils first, center cards last (on top), like the reference.
  cards.sort((a, b) => a.n - b.n);

  const intro = interpolate(t, [0, 16], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleSize = Math.min(width * 0.066, height * 0.11);

  return (
    <AbsoluteFill
      showInTimeline={false}
      className={className}
      style={{ backgroundColor: stage, fontFamily: face }}
    >
      {cards.map((card) => {
        const p = archimedeanPoint(card.n, R, turns);
        const dist = Math.hypot(p.x, p.y);

        let opacity = 1;
        if (card.tt < fadeIn) opacity = card.tt / fadeIn;
        else if (fadeOut > 0 && card.tt > 100 - fadeOut)
          opacity = (100 - card.tt) / fadeOut;
        if (opacity < 0.01) return null;

        const scale = sizeScale(dist, R, sizeAttenuation);
        if (scale < 0.002) return null;

        // Tangent of the spiral at this point → the card's rotation.
        const p2 = archimedeanPoint(Math.min(card.n + 0.001, 1), R, turns);
        const angleDeg = (Math.atan2(p2.y - p.y, p2.x - p.x) * 180) / Math.PI;

        // Long edge = baseSize·scale; the short edge follows cardAspect.
        const ch = baseSize * scale;
        const cw = ch * cardAspect;
        const rad = (cornerRadius / 20) * (Math.min(cw, ch) / 2);

        // Only the few tiny cards passing right behind the title get a light
        // blur (a cheap per-element filter on a handful of small cards — nothing
        // like the frame-wide backdrop blur that stalled the player). Everything
        // in the visible outer band stays sharp.
        const centerBlurR = minDim * 0.16;
        const blurPx = dist < centerBlurR ? (1 - dist / centerBlurR) * 4 : 0;

        return (
          <div
            key={card.key}
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              width: cw,
              height: ch,
              marginLeft: -cw / 2,
              marginTop: -ch / 2,
              zIndex: Math.round(card.n * 8),
              translate: `${p.x.toFixed(2)}px ${p.y.toFixed(2)}px`,
              rotate: `${angleDeg.toFixed(2)}deg`,
              opacity: opacity * intro,
              filter:
                blurPx > 0.15 ? `blur(${blurPx.toFixed(2)}px)` : undefined,
              borderRadius: rad,
              overflow: "hidden",
              backgroundColor: mixOklch(stage, tokens.card, 0.35),
              boxShadow: `0 ${(ch * 0.12).toFixed(1)}px ${(ch * 0.3).toFixed(1)}px ${withAlpha(
                mixOklch(stage, "#000", 0.75),
                0.4,
              )}`,
            }}
          >
            <OrbitTile
              src={artwork.length ? artwork[card.imgIdx % nImgs] : undefined}
              fill={PLACEHOLDER_FILLS[card.imgIdx % PLACEHOLDER_FILLS.length]}
            />
          </div>
        );
      })}

      {/* Soft focus pool behind the lockup: a radial dark scrim so the title
          reads. This is a plain gradient (no backdrop-filter) — the earlier
          backdrop blur re-blurred every moving card each frame and froze the
          player. The slight softness behind the text comes from the small
          center cards' own light blur (see `centerBlur` in the card loop). */}
      {/* The scrim deepens the page behind the lockup; with no page there is
          nothing to deepen, and on a transparent one it would be black. */}
      {(title || subtitle || buttonLabel) && parseColor(stage).alpha !== 0 ? (
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: width * 0.66,
            height: height * 0.5,
            marginLeft: -(width * 0.66) / 2,
            marginTop: -(height * 0.5) / 2,
            borderRadius: "50%",
            backgroundImage: `radial-gradient(ellipse at center, ${withAlpha(
              stage,
              0.62,
            )} 0%, ${withAlpha(stage, 0.34)} 42%, transparent 70%)`,
            opacity: intro,
            zIndex: 9,
          }}
        />
      ) : null}

      <AbsoluteFill
        showInTimeline={false}
        style={{
          alignItems: "center",
          justifyContent: "center",
          textAlign: "center",
          zIndex: 10,
        }}
      >
        {title ? (
          <div
            style={{
              fontSize: titleSize,
              fontWeight: 500,
              letterSpacing: "-0.015em",
              lineHeight: 1.08,
              color: ink,
              maxWidth: "82%",
              opacity: interpolate(t, [8, 34], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              translate: `0px ${interpolate(t, [8, 34], [titleSize * 0.4, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.cubic),
              })}px`,
              filter: `blur(${interpolate(t, [8, 30], [8, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })}px)`,
            }}
          >
            {title}
          </div>
        ) : null}

        {subtitle ? (
          <div
            style={{
              marginTop: titleSize * 0.42,
              fontSize: titleSize * 0.26,
              letterSpacing: "0.02em",
              color: ink,
              opacity:
                0.65 *
                interpolate(t, [16, 40], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
              translate: `0px ${interpolate(
                t,
                [16, 40],
                [titleSize * 0.25, 0],
                {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.out(Easing.cubic),
                },
              )}px`,
            }}
          >
            {subtitle}
          </div>
        ) : null}

        {buttonLabel ? (
          <div
            style={{
              marginTop: titleSize * 0.5,
              padding: `${titleSize * 0.14}px ${titleSize * 0.34}px`,
              borderRadius: 9999,
              backgroundColor: withAlpha(ink, 0.14),
              fontSize: titleSize * 0.23,
              fontWeight: 500,
              color: ink,
              opacity: interpolate(t, [24, 44], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              scale: String(
                interpolate(t, [24, 48], [0.7, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.out(Easing.back(1.4)),
                }),
              ),
            }}
          >
            {buttonLabel}
          </div>
        ) : null}
      </AbsoluteFill>

      {footerLeft || footerCenter || footerRight ? (
        <div
          style={{
            position: "absolute",
            left: width * 0.05,
            right: width * 0.05,
            bottom: height * 0.032,
            display: "flex",
            justifyContent: "space-between",
            fontSize: titleSize * 0.22,
            color: ink,
            opacity:
              0.78 *
              interpolate(t, [30, 50], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
            zIndex: 10,
          }}
        >
          <span>{footerLeft}</span>
          <span>{footerCenter}</span>
          <span>{footerRight}</span>
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

