type OrbitGalleryElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OrbitGalleryScene>;

/** What a prop falls back to when Studio does not pass it, reset included. */
const OrbitGalleryDefaults = {
  title: "A whole new universe",
  subtitle: "Article — The Design Process",
  buttonLabel: "Explore",
  turns: 3,
  spacing: 5,
  spread: 7,
  imageSize: 172,
  sizeAttenuation: 2,
  cornerRadius: 5,
  orbitSeconds: 40,
  background: "transparent",
  textColor: "#141414",
  fontFamily: "Default",
  speed: 1,
  mode: "light",
} satisfies Partial<OrbitGalleryElementProps>;

const OrbitGallerySchema = {
  ...Interactive.baseSchema,
  title: {
    type: "text-content",
    default: "A whole new universe",
    description: "Title",
  },
  subtitle: {
    type: "text-content",
    default: "Article — The Design Process",
    description: "Subtitle",
  },
  buttonLabel: {
    type: "text-content",
    default: "Explore",
    description: "Button label",
  },
  textColor: {
    type: "color",
    default: "#141414",
    description: "Text color",
    keyframable: false,
  },
  fontFamily: {
    type: "enum",
    default: "Default",
    description: "Font",
    variants: {
      Default: {},
      Inter: {},
      Geist: {},
      "Space Grotesk": {},
      Outfit: {},
      Montserrat: {},
      "Instrument Serif": {},
    },
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function OrbitGalleryFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const OrbitGalleryInner = forwardRef<
  HTMLDivElement,
  OrbitGalleryElementProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      freeze,
      hidden,
      showInTimeline,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    const rest = { ...OrbitGalleryDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside the Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Orbit Gallery"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <OrbitGalleryFade>
            <OrbitGalleryScene key={key} {...rest} />
          </OrbitGalleryFade>
        </div>
      </Sequence>
    );
  },
);

export const OrbitGallery = Interactive.withSchema({
  Component: OrbitGalleryInner,
  componentName: "<OrbitGallery>",
  schema: OrbitGallerySchema,
  supportsEffects: false,
});
